CREATE TABLE fee_rule (
 id CHAR(36) PRIMARY KEY,version INT NOT NULL UNIQUE,listing_fee_cent BIGINT NOT NULL,commission_bps INT NOT NULL,channel_fee_bps INT NOT NULL,minimum_withdrawal_cent BIGINT NOT NULL,freeze_seconds BIGINT NOT NULL,effective_at TIMESTAMP(6) NOT NULL,created_by BIGINT NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
 CHECK(listing_fee_cent>=1 AND commission_bps>=0 AND channel_fee_bps>=0 AND commission_bps+channel_fee_bps<=10000 AND minimum_withdrawal_cent>0 AND freeze_seconds>=0),INDEX ix_fee_effective(effective_at));
INSERT INTO fee_rule VALUES('00000000-0000-0000-0000-000000000001',1,100,1500,60,100,604800,'2020-01-01 00:00:00',0,CURRENT_TIMESTAMP(6));
CREATE TABLE material(id CHAR(36) PRIMARY KEY,owner_id BIGINT NOT NULL,video_id CHAR(36) NOT NULL,current_version INT NOT NULL,status VARCHAR(32) NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),FOREIGN KEY(video_id) REFERENCES video_assets(video_id),INDEX ix_material_owner(owner_id,created_at),INDEX ix_material_market(status,created_at),CHECK(status IN('DRAFT','PUBLISH_PAYMENT_PENDING','PUBLISHED','OFF_SHELF','REJECTED')));
CREATE TABLE license_version(id CHAR(36) PRIMARY KEY,material_id CHAR(36) NOT NULL,version INT NOT NULL,terms JSON NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),UNIQUE(material_id,version),FOREIGN KEY(material_id) REFERENCES material(id));
CREATE TABLE material_version(material_id CHAR(36) NOT NULL,version INT NOT NULL,title VARCHAR(128) NOT NULL,description TEXT NOT NULL,category VARCHAR(64) NOT NULL,tags JSON NOT NULL,price_cent BIGINT NOT NULL,license_id CHAR(36) NOT NULL,source_key VARCHAR(255) NOT NULL,source_version CHAR(64) NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(material_id,version),FOREIGN KEY(material_id) REFERENCES material(id),FOREIGN KEY(license_id) REFERENCES license_version(id),CHECK(price_cent>0 AND price_cent<=1000000000000));
CREATE TABLE commerce_user_guard(user_id BIGINT PRIMARY KEY,cancel_day DATE NULL,cancel_count INT NOT NULL DEFAULT 0);
CREATE TABLE business_order(id CHAR(36) PRIMARY KEY,user_id BIGINT NOT NULL,creator_id BIGINT NOT NULL,order_type VARCHAR(16) NOT NULL,material_id CHAR(36) NOT NULL,material_version INT NOT NULL,status VARCHAR(24) NOT NULL,idempotency_key VARCHAR(100) NOT NULL,request_hash CHAR(64) NOT NULL,amount_cent BIGINT NOT NULL,commission_cent BIGINT NOT NULL,channel_fee_cent BIGINT NOT NULL,creator_cent BIGINT NOT NULL,rule_version INT NOT NULL,fee_snapshot JSON NOT NULL,license_snapshot JSON NOT NULL,license_confirmed_at TIMESTAMP(6) NOT NULL,expires_at TIMESTAMP(6) NOT NULL,paid_at TIMESTAMP(6) NULL,cancel_reason VARCHAR(32) NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),UNIQUE(user_id,idempotency_key),FOREIGN KEY(material_id,material_version) REFERENCES material_version(material_id,version),FOREIGN KEY(rule_version) REFERENCES fee_rule(version),CHECK(order_type IN('LISTING','PURCHASE')),CHECK(status IN('PENDING','PAYING','CLOSING','CANCELLED','PAID','REFUND_PENDING','REFUNDED')),CHECK(amount_cent>0 AND amount_cent=commission_cent+channel_fee_cent+creator_cent AND commission_cent>=0 AND channel_fee_cent>=0 AND creator_cent>=0),INDEX ix_order_user(user_id,created_at),INDEX ix_order_close(status,expires_at));
CREATE TABLE payment(id CHAR(36) PRIMARY KEY,order_id CHAR(36) NOT NULL UNIQUE,provider VARCHAR(16) NOT NULL,status VARCHAR(24) NOT NULL,amount_cent BIGINT NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'CNY',channel_id VARCHAR(128) NULL UNIQUE,channel_fee_actual_cent BIGINT NULL,checkout_url VARCHAR(2000) NULL,last_error VARCHAR(500) NULL,paid_at TIMESTAMP(6) NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),FOREIGN KEY(order_id) REFERENCES business_order(id),CHECK(status IN('CREATED','PENDING','SUCCEEDED','CLOSED')),CHECK(amount_cent>0));
CREATE TABLE payment_notification(provider VARCHAR(16) NOT NULL,notification_id VARCHAR(128) NOT NULL,payload_hash CHAR(64) NOT NULL,payment_id CHAR(36) NULL,received_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(provider,notification_id));
CREATE TABLE refund(id CHAR(36) PRIMARY KEY,order_id CHAR(36) NOT NULL UNIQUE,payment_id CHAR(36) NOT NULL,requested_by BIGINT NOT NULL,idempotency_key VARCHAR(100) NOT NULL,amount_cent BIGINT NOT NULL,status VARCHAR(24) NOT NULL,channel_id VARCHAR(128) NULL,reason VARCHAR(500) NOT NULL,last_error VARCHAR(500) NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),FOREIGN KEY(order_id) REFERENCES business_order(id),FOREIGN KEY(payment_id) REFERENCES payment(id),CHECK(status IN('PENDING','PROCESSING','SUCCEEDED','FAILED')));
CREATE TABLE entitlement(id CHAR(36) PRIMARY KEY,order_id CHAR(36) NOT NULL UNIQUE,user_id BIGINT NOT NULL,material_id CHAR(36) NOT NULL,material_version INT NOT NULL,status VARCHAR(16) NOT NULL,license_snapshot JSON NOT NULL,source_key VARCHAR(255) NOT NULL,expires_at TIMESTAMP(6) NULL,revoked_at TIMESTAMP(6) NULL,revoke_reason VARCHAR(500) NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(order_id) REFERENCES business_order(id),FOREIGN KEY(material_id,material_version) REFERENCES material_version(material_id,version),CHECK(status IN('ACTIVE','REVOKED')),INDEX ix_entitlement_user(user_id,created_at));
CREATE TABLE audit_log(id CHAR(36) PRIMARY KEY,actor_id BIGINT NOT NULL,action VARCHAR(64) NOT NULL,aggregate_id VARCHAR(64) NOT NULL,details JSON NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),INDEX ix_audit_aggregate(aggregate_id,created_at));
CREATE TABLE mock_channel_payment(payment_id CHAR(36) PRIMARY KEY,amount_cent BIGINT NOT NULL,status VARCHAR(24) NOT NULL,channel_id VARCHAR(128) NOT NULL UNIQUE,paid_at TIMESTAMP(6) NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE mock_channel_refund(refund_id CHAR(36) PRIMARY KEY,payment_id CHAR(36) NOT NULL,amount_cent BIGINT NOT NULL,status VARCHAR(24) NOT NULL,channel_id VARCHAR(128) NOT NULL UNIQUE,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TRIGGER material_version_no_update BEFORE UPDATE ON material_version FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Material versions are immutable';
CREATE TRIGGER license_version_no_update BEFORE UPDATE ON license_version FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='License versions are immutable';
